module freq_div(
    input CLK_in,
    input RST,
    output CLK_50,
    output CLK_10,
    output CLK_1
);

reg [3:0] cnt_50 = 0;
reg [3:0] cnt_10 = 0;
reg [3:0] cnt_1 = 0;

always @(posedge CLK_in or posedge RST) begin
    if (RST) begin
        cnt_50 <= 0;
        cnt_10 <= 0;
        cnt_1 <= 0;
    end
    else begin
        cnt_50 <= cnt_50 + 1;
        if (cnt_50 == 4'b1001) begin
            cnt_50 <= 0;
        end

        cnt_10 <= cnt_10 + 1;
        if (cnt_10 == 4'b1001) begin
            cnt_10 <= 0;
        end

        cnt_1 <= cnt_1 + 1;
        if (cnt_1 == 4'b1100) begin
            cnt_1 <= 0;
        end
    end
end

assign CLK_50 = (cnt_50 == 4'b1001) ? ~CLK_50 : CLK_50;
assign CLK_10 = (cnt_10 == 4'b1001) ? ~CLK_10 : CLK_10;
assign CLK_1 = (cnt_1 == 4'b1100) ? ~CLK_1 : CLK_1;

endmodule
